<?= $this->section('scripts') ?><script>
function resetTypeForm(){document.getElementById('formTitle').textContent='Add Cylinder Type';document.getElementById('type_id').value='';['code','name','capacity_kg','tare_weight_kg','empty_cylinder_price','sort_order'].forEach(n=>document.getElementById('type_'+n).value='');document.getElementById('type_is_active').checked=true;}
function editType(t){document.getElementById('formTitle').textContent='Edit Cylinder Type';document.getElementById('type_id').value=t.id;document.getElementById('type_code').value=t.code||'';document.getElementById('type_name').value=t.name||'';document.getElementById('type_capacity_kg').value=t.capacity_kg||'';document.getElementById('type_tare_weight_kg').value=t.tare_weight_kg??'';document.getElementById('type_empty_cylinder_price').value=t.empty_cylinder_price??0;document.getElementById('type_sort_order').value=t.sort_order||0;document.getElementById('type_is_active').checked=!!Number(t.is_active);bootstrap.Modal.getOrCreateInstance(document.getElementById('form')).show();}
</script><?= $this->endSection() ?>
